from collections.abc import Mapping
from copy import deepcopy


def select_values(document, path, variables=None):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if variables is None:
        variables = {}
    if not isinstance(variables, Mapping):
        raise TypeError("variables must be a mapping")
    if path == "":
        return deepcopy([document])

    segments = path.split("/")
    if any(segment == "" for segment in segments):
        raise ValueError("path contains an empty segment")

    current = [document]
    for raw_segment in segments:
        segment = raw_segment
        if raw_segment.startswith("$"):
            name = raw_segment[1:]
            if not name or not name.isidentifier():
                raise ValueError("invalid variable segment")
            if name not in variables:
                raise KeyError(name)
            segment = variables[name]
            if not isinstance(segment, str):
                raise TypeError("variable values must be strings")
            if segment == "":
                raise ValueError("variable produced an empty segment")

        following = []
        for value in current:
            if segment == "*":
                if isinstance(value, Mapping):
                    following.extend(value.values())
                elif isinstance(value, list):
                    following.extend(value)
                else:
                    raise TypeError("wildcard requires a dictionary or list")
            elif isinstance(value, Mapping):
                if segment not in value:
                    raise KeyError(segment)
                following.append(value[segment])
            elif isinstance(value, list):
                if segment.startswith("-") and segment[1:].isdecimal():
                    raise IndexError(int(segment))
                if not segment.isdecimal():
                    raise TypeError("list indexes must be non-negative decimals")
                index = int(segment)
                if index >= len(value):
                    raise IndexError(index)
                following.append(value[index])
            else:
                raise TypeError("cannot descend into a scalar")
        current = following

    return current

